/// The semantic difference pattern generated by a workload.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum DiffModel {
    /// Every event adds positive relation weight and never retracts.
    InsertOnly,
    /// Insertions and retractions are generated from a checked relation model.
    ValidChurn,
}

impl DiffModel {
    /// Returns the stable machine-readable model name.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::InsertOnly => "insert_only",
            Self::ValidChurn => "valid_churn",
        }
    }
}

/// A stable synthetic Change workload family.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum WorkloadPersona {
    /// No logical columns; isolates the physical diff and IPC framing.
    DiffOnlyControl,
    /// A 16-column layout spanning every currently supported Arrow layout.
    LayoutV1_16,
    /// Eight fixed-width event columns.
    FixedEvent8,
    /// Sixteen mixed fixed/variable-width and nullable event columns.
    MixedEvent16,
    /// Sixty-four non-null numeric columns.
    WideNumeric64,
    /// Four columns dominated by one configurable Binary payload.
    BlobEvent4,
    /// Eight top-level columns containing List and Struct subtrees.
    NestedEvent8,
    /// A non-zero-offset slice of the sixteen-column mixed layout.
    SlicedMixed16,
    /// A deterministic rotation through all concrete personas.
    Heterogeneous,
}

impl WorkloadPersona {
    /// Every workload persona in stable reporting order.
    pub const ALL: [Self; 9] = [
        Self::DiffOnlyControl,
        Self::LayoutV1_16,
        Self::FixedEvent8,
        Self::MixedEvent16,
        Self::WideNumeric64,
        Self::BlobEvent4,
        Self::NestedEvent8,
        Self::SlicedMixed16,
        Self::Heterogeneous,
    ];

    /// Returns the stable machine-readable persona name.
    #[must_use]
    pub const fn name(self) -> &'static str {
        self.descriptor().name
    }

    /// Returns the stable descriptor for this persona.
    #[must_use]
    pub const fn descriptor(self) -> &'static WorkloadDescriptor {
        match self {
            Self::DiffOnlyControl => &DIFF_ONLY_DESCRIPTOR,
            Self::LayoutV1_16 => &LAYOUT_V1_DESCRIPTOR,
            Self::FixedEvent8 => &FIXED_EVENT_DESCRIPTOR,
            Self::MixedEvent16 => &MIXED_EVENT_DESCRIPTOR,
            Self::WideNumeric64 => &WIDE_NUMERIC_DESCRIPTOR,
            Self::BlobEvent4 => &BLOB_EVENT_DESCRIPTOR,
            Self::NestedEvent8 => &NESTED_EVENT_DESCRIPTOR,
            Self::SlicedMixed16 => &SLICED_MIXED_DESCRIPTOR,
            Self::Heterogeneous => &HETEROGENEOUS_DESCRIPTOR,
        }
    }

    /// Resolves the concrete persona used at `ordinal`.
    #[must_use]
    pub const fn concrete_at(self, ordinal: usize) -> Self {
        if matches!(self, Self::Heterogeneous) {
            HETEROGENEOUS_ROTATION[ordinal % HETEROGENEOUS_ROTATION.len()]
        } else {
            self
        }
    }

    /// Returns the selected logical field indices for a legal profile.
    #[must_use]
    pub fn projection_indices(self, profile: ProjectionProfile) -> Option<&'static [usize]> {
        let descriptor = self.descriptor();
        if descriptor.schemas.len() != 1 {
            return None;
        }
        descriptor.schemas[0].projection(profile)
    }
}

/// A projection shape shared by correctness and performance protocols.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum ProjectionProfile {
    /// Select no business fields; the diff remains implicit.
    DiffOnly,
    /// Select only the event key.
    KeyOnly,
    /// Select a small, potentially non-adjacent subset.
    Sparse,
    /// Select most business fields while omitting the primary wide payload.
    Dense,
    /// Select only the primary variable-width payload.
    PayloadOnly,
    /// Select every business field through the projected decoder.
    Identity,
}

impl ProjectionProfile {
    /// Every projection profile in stable reporting order.
    pub const ALL: [Self; 6] = [
        Self::DiffOnly,
        Self::KeyOnly,
        Self::Sparse,
        Self::Dense,
        Self::PayloadOnly,
        Self::Identity,
    ];

    /// Returns the stable machine-readable profile name.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::DiffOnly => "diff_only",
            Self::KeyOnly => "key_only",
            Self::Sparse => "sparse",
            Self::Dense => "dense",
            Self::PayloadOnly => "payload_only",
            Self::Identity => "identity",
        }
    }
}

/// One legal projection for a concrete Schema descriptor.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ProjectionDescriptor {
    /// Semantic projection profile.
    pub profile: ProjectionProfile,
    /// Strictly increasing top-level logical field indices.
    pub selected_columns: &'static [usize],
}

/// Structural facts about one concrete logical Schema.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SchemaDescriptor {
    /// Stable Schema shape name.
    pub name: &'static str,
    /// Top-level business columns, excluding the physical diff.
    pub business_columns: usize,
    /// Physical top-level columns, including the leading diff.
    pub physical_columns: usize,
    /// Logical leaf fields after recursively expanding List and Struct nodes.
    pub leaf_columns: usize,
    /// Nullable top-level business fields.
    pub top_level_nullable_columns: usize,
    /// Top-level Utf8 or Binary business fields.
    pub top_level_variable_width_columns: usize,
    /// Top-level List or Struct business fields.
    pub top_level_nested_columns: usize,
    /// Nullable logical fields across the complete field tree.
    pub total_nullable_fields: usize,
    /// Utf8 or Binary leaf fields across the complete field tree.
    pub variable_width_leaf_columns: usize,
    /// List or Struct nodes across the complete field tree.
    pub total_nested_fields: usize,
    /// Stable compact description of the logical field types.
    pub type_summary: &'static str,
    /// Legal projection profiles for this exact Schema.
    pub projection_profiles: &'static [ProjectionDescriptor],
}

impl SchemaDescriptor {
    /// Returns the selected indices for `profile`, if the profile is legal.
    #[must_use]
    pub fn projection(self, profile: ProjectionProfile) -> Option<&'static [usize]> {
        self.projection_profiles
            .iter()
            .find(|descriptor| descriptor.profile == profile)
            .map(|descriptor| descriptor.selected_columns)
    }
}

/// Stable metadata for a workload persona.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct WorkloadDescriptor {
    /// Stable workload name.
    pub name: &'static str,
    /// Difference model generated by this workload.
    pub diff_model: DiffModel,
    /// Concrete Schemas used by this persona. Heterogeneous workloads expose
    /// every Schema in their deterministic rotation.
    pub schemas: &'static [SchemaDescriptor],
}

