const WIDE_IDENTITY: [usize; 64] = make_indices::<64>();
const WIDE_DENSE: [usize; 63] = make_indices::<63>();

const fn make_indices<const N: usize>() -> [usize; N] {
    let mut values = [0; N];
    let mut index = 0;
    while index < N {
        values[index] = index;
        index += 1;
    }
    values
}

